solution:
public class TrianguloAsteriscos {
    public static void main(String[] args) {
        int filas = 5;

        for (int f = 1; f <= filas; f++) {
            for (int a = 0; a < f; a++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }
}

