solution:
public class NumerosPrimos {
    public static void main(String[] args) {
        System.out.println("Números primos del 2 al 50:");

        for (int n = 2; n <= 50; n++) {
            boolean esPrimo = true;

            for (int d = 2; d <= Math.sqrt(n); d++) {
                if (n % d == 0) {
                    esPrimo = false;
                    break;
                }
            }

            if (esPrimo) {
                System.out.print(n + " ");
            }
        }
        System.out.println();
    }
}
